#include <stdio.h>
struct Date { int day, month, year; };
struct Ticket { int id; struct Date opened; };
int main(void) {
 struct Ticket tickets[2] = {{10,{2,11,2026}}, {11,{5,11,2026}}};
 for (size_t i=0; i<2; ++i)
  printf("%d: %02d-%02d-%d\n", tickets[i].id, tickets[i].opened.day, tickets[i].opened.month, tickets[i].opened.year);
 return 0;
}
